mapper.select:
SELECT id, task_type, operation, target_type, batch_id, is_batch, status, stage, progress,
       total_count, success_count, failure_count, cancelled_count, idempotency_key,
       idempotency_payload_hash, error_message, error_detail, attempt, version,
       created_at, updated_at, started_at, completed_at
FROM management_task

    AND task_type = #{taskType}
    AND status = #{status}
    AND batch_id = #{batchId}
    AND target_type = #{targetType}

        AND id IN #{taskId}


ORDER BY created_at DESC

mapper.update:
UPDATE management_task
SET stage = #{stage}, updated_at = #{updatedAt}
, progress = #{progress}
, status = 'RUNNING', started_at = #{startedAt}
WHERE id = #{taskId}
